def is_safe_name(name: str) -> bool:
    """True when name is a non-empty relative path with no ".." segment, no leading "/", no backslash and no NUL, so it stays inside the notes directory."""
    ex is_safe_name("a.txt") == True
    ex is_safe_name("sub/a.txt") == True
    ex is_safe_name("") == False
    ex is_safe_name("../secret") == False
    ex is_safe_name("a/../../b") == False
    ex is_safe_name("/etc/passwd") == False
    ex is_safe_name("..\\x") == False
    if name.byte_len() < 1:
        return False
    if name.startswith("/"):
        return False
    if "\\" in name:
        return False
    if "\0" in name:
        return False
    for seg in name.split("/"):
        if seg == "..":
            return False
    return True

def count_readable(names: list[str]) -> int uses fs:
    """Count the names that are files in the directory `notes` and have non-empty readable content. Unsafe names are skipped, and a missing or unreadable file reads as "" and is not counted. All reads happen inside `with fs = fs.sub("notes"):`, so no name can reach outside `notes`."""
    pre names.len() >= 0
    post out >= 0
    post out <= names.len()
    n = 0
    with fs = fs.sub("notes"):
        for name in names:
            if not is_safe_name(name):
                continue
            text = fs.read_text(name) else ""
            if text.byte_len() > 0:
                n += 1
    return n
